-- Additional management contracts; hsweb remains the authority for users and permissions.
CREATE TABLE s_dictionary (id varchar(64) PRIMARY KEY,name varchar(255) NOT NULL,classified varchar(64),describe varchar(255),create_time bigint,creator_id varchar(64),status smallint DEFAULT 1,i18n_messages text);
CREATE TABLE s_dictionary_item (id varchar(64) PRIMARY KEY,dict_id varchar(64) NOT NULL REFERENCES s_dictionary(id) ON DELETE CASCADE,name varchar(255),value varchar(255),text varchar(255),value_type varchar(255),status smallint DEFAULT 1,describe varchar(255),search_code varchar(255),ordinal integer NOT NULL,parent_id varchar(64),path varchar(128),sort_index bigint,_level integer,i18n_messages text,UNIQUE(dict_id,value),UNIQUE(dict_id,ordinal));
CREATE INDEX idx_dic_item_dic_id ON s_dictionary_item(dict_id);
CREATE INDEX idx_dic_item_ordinal ON s_dictionary_item(ordinal);
CREATE INDEX idx_dic_item_path ON s_dictionary_item(path);
CREATE TABLE proto_organization (id varchar(64) PRIMARY KEY,name varchar(128) NOT NULL,code varchar(64),type varchar(32),describe varchar(1024),properties text,parent_id varchar(64),path varchar(128),sort_index bigint,_level integer);
CREATE TABLE proto_position (id varchar(64) PRIMARY KEY,name varchar(128) NOT NULL,org_id varchar(64) NOT NULL REFERENCES proto_organization(id),code varchar(64),description varchar(1024),roles text,parent_id varchar(64),path varchar(128),sort_index bigint,_level integer);
CREATE INDEX proto_position_org_idx ON proto_position(org_id);
CREATE TABLE proto_role_group (id varchar(64) PRIMARY KEY,name varchar(128) NOT NULL,parent_id varchar(64),path varchar(128),sort_index bigint,_level integer);
CREATE TABLE proto_user_detail (id varchar(64) PRIMARY KEY REFERENCES s_user(id) ON DELETE CASCADE,email varchar(255),telephone varchar(64),avatar varchar(1024));
CREATE TABLE proto_system_config (id varchar(64) PRIMARY KEY,properties text);
CREATE TABLE proto_role_menu_grant (id varchar(64) PRIMARY KEY REFERENCES s_dimension(id) ON DELETE CASCADE,menus text,managed_permissions text);
ALTER TABLE proto_menu ADD COLUMN code varchar(128),ADD COLUMN icon varchar(128),ADD COLUMN component_code varchar(128),ADD COLUMN app_id varchar(64),ADD COLUMN options text,ADD COLUMN permissions text,ADD COLUMN buttons text,ADD COLUMN i18n_messages text;
UPDATE proto_menu SET code=id WHERE code IS NULL;
CREATE UNIQUE INDEX proto_menu_code_idx ON proto_menu(code) WHERE code IS NOT NULL AND code<>'';
ALTER TABLE s_dimension ALTER COLUMN name TYPE varchar(128);
UPDATE s_dimension SET properties='{"groupId":"default","state":"enabled"}' WHERE type_id='role' AND properties IS NULL;

UPDATE proto_menu SET code='protohub/Project',component_code='protohub/Project' WHERE id='protohub';
